INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4a204bf2-884a-4d17-b5fa-501aec2ff95d', '769d0128-302f-42cb-ab66-3182ac6c636b', 'A', 'Plain Lidocaine 1% without Adrenaline (Epinephrine)', 1, 'Correct. Infiltration of local anaesthetic with adrenaline (vasoconstrictor) into end-artery regions (fingers, toes, nose, ear, penis) carries high risk of severe ischaemia and gangrenous tissue necrosis.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f7040900-fb6e-4309-8a2f-e5c000a829a5', '769d0128-302f-42cb-ab66-3182ac6c636b', 'B', 'Lidocaine 2% with Adrenaline 1:80,000 solution', 0, 'Contraindicated and dangerous for digital ring block due to end-arteriole vasospasm.', 1, 1789735204);
