INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('026de7c9-5dc4-4ca6-b0a3-08c860b2a51a', '0bb40213-51e6-4072-9def-d01ee361400e', 'B', 'Lidocaine 2% with Adrenaline 1:80,000 solution', 0, 'Contraindicated and dangerous for digital ring block due to end-arteriole vasospasm.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cf771f79-91fd-48be-bbc1-ec98a4c08958', '0bb40213-51e6-4072-9def-d01ee361400e', 'C', 'Bupivacaine 0.5% with Adrenaline 1:200,000 for rapid local digital infiltration', 0, 'Strictly contraindicated for end-artery infiltration.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('584557b8-4e3d-42a7-a603-8d1a717308ed', '0bb40213-51e6-4072-9def-d01ee361400e', 'D', 'Cocaine hydrochloride topical paste', 0, 'Deprecated toxic practice for peripheral skin suturing.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a9033e2a-b73b-4f54-85b5-c6e7da9421db', '0bb40213-51e6-4072-9def-d01ee361400e', 'E', 'Inject exceeding maximum plain lidocaine safe limit of 3 mg/kg (or 200 mg total)', 0, 'Dose violation leading to central nervous system and cardiovascular toxicity.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('47c73826-cc15-4524-9754-fd293237b1f1', '0bb40213-51e6-4072-9def-d01ee361400e', 'Never use adrenaline-containing local anaesthetics in areas with end-artery circulation (digits, ear, nose, penis).', 'Intralipid (20% lipid emulsion) is the specific rescue agent for systemic local anaesthetic toxicity (LAST). Reference: BNF Section 15.2 & Resuscitation Council UK.', 'BNF Section 15.2 & Resuscitation Council UK', 1789735204, 1789735204);
