INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'ACP-Q-1866', 1, 'published', 'p-mpharm', 'sub-paracetamol-tox', 'hard', 'sba', 'gp', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('e504c810-a8e6-4370-9e5e-237dc294f1f7', '1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'A 24-year-old patient reports ingesting 20 g of paracetamol in divided doses over the past 14 hours ("staggered overdose"). Baseline blood tests show normal ALT and normal creatinine. (Case Ref: POISONING-EMERGENCY-1866). Relevant physiological and medication history have been reviewed.', 'What is the mandatory clinical treatment decision regarding Acetylcysteine?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7c69bbd2-2aea-4f9d-976f-f1fadbe92afb', '1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'A', 'Initiate IV Acetylcysteine immediately without waiting for serum paracetamol levels or nomogram plotting', 1, 'Correct. In staggered paracetamol overdoses (taken over > 1 hour), the paracetamol treatment nomogram CANNOT be used. Acetylcysteine must be commenced immediately regardless of the serum paracetamol concentration.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3cd953f4-eb76-4b44-8cd2-38c4d3c7db8b', '1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'B', 'Wait for the 4-hour serum paracetamol level and plot on the single-ingestion nomogram curve', 0, 'Fatal error. The nomogram is validated ONLY for acute single ingestions within 4-15 hours. Staggered overdoses render the nomogram uninterpretable.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bf112f9a-7220-41a1-bb9a-d73ba7c955d1', '1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'C', 'Administer Oral Activated Charcoal 50 g at 14 hours post-ingestion', 0, 'Ineffective and contraindicated. Activated charcoal is only effective within 1 hour of ingestion and impairs oral antidotes.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('07a96126-05da-4327-8f7a-2c81559a3490', '1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'D', 'Withhold acetylcysteine because baseline transaminases (ALT) are currently normal', 0, 'Fatal error. ALT rises 24-48 hours after ingestion; waiting for hepatotoxicity before treating causes irreversible liver failure.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ec6b00cd-d2cd-41be-9f46-0f992329e025', '1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'E', 'Stop acetylcysteine infusion immediately if mild flush develops without anaphylactoid assessment', 0, 'Incorrect management. Common non-IgE mediated reactions can be managed by pausing infusion, giving antihistamine, and restarting at slower rate.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('c71d20c1-e59e-4871-aa30-be467a6b0dc1', '1ec53e46-01fa-476c-8b87-6326fd4d2aeb', 'Never use the paracetamol nomogram for staggered overdoses. Start Acetylcysteine immediately.', 'Snap 12-hour or simplified 2-bag IV acetylcysteine regimens reduce adverse hypersensitivity reactions. Reference: TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose.', 'TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose', 1789735204, 1789735204);
