INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f23e3b0f-dd00-4806-8672-bc5c9040c74e', '0a14c1a0-3153-4ec2-9870-401a85ec7807', 'B', 'Wait for the 4-hour serum paracetamol level and plot on the single-ingestion nomogram curve', 0, 'Fatal error. The nomogram is validated ONLY for acute single ingestions within 4-15 hours. Staggered overdoses render the nomogram uninterpretable.', 1, 1789735204);
