INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('991310bd-2dee-4063-81d3-0300e691c56b', '6bf1099c-7947-4b1f-bac0-9a3b9c7233aa', 'A', 'Initiate IV Acetylcysteine immediately without waiting for serum paracetamol levels or nomogram plotting', 1, 'Correct. In staggered paracetamol overdoses (taken over > 1 hour), the paracetamol treatment nomogram CANNOT be used. Acetylcysteine must be commenced immediately regardless of the serum paracetamol concentration.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('809494f7-73a6-40fd-99c0-ab7e51dd7b75', '6bf1099c-7947-4b1f-bac0-9a3b9c7233aa', 'B', 'Wait for the 4-hour serum paracetamol level and plot on the single-ingestion nomogram curve', 0, 'Fatal error. The nomogram is validated ONLY for acute single ingestions within 4-15 hours. Staggered overdoses render the nomogram uninterpretable.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('94db61fa-14e2-4db1-a47c-60759c840292', '6bf1099c-7947-4b1f-bac0-9a3b9c7233aa', 'C', 'Administer Oral Activated Charcoal 50 g at 14 hours post-ingestion', 0, 'Ineffective and contraindicated. Activated charcoal is only effective within 1 hour of ingestion and impairs oral antidotes.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('786eca4c-e4d8-4030-9f6c-562ca9a13a12', '6bf1099c-7947-4b1f-bac0-9a3b9c7233aa', 'D', 'Withhold acetylcysteine because baseline transaminases (ALT) are currently normal', 0, 'Fatal error. ALT rises 24-48 hours after ingestion; waiting for hepatotoxicity before treating causes irreversible liver failure.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('54b34b52-1807-43fd-947b-7d66c144372b', '6bf1099c-7947-4b1f-bac0-9a3b9c7233aa', 'E', 'Stop acetylcysteine infusion immediately if mild flush develops without anaphylactoid assessment', 0, 'Incorrect management. Common non-IgE mediated reactions can be managed by pausing infusion, giving antihistamine, and restarting at slower rate.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('56b51bc2-6ce1-40e0-ad66-d16d52abd7c5', '6bf1099c-7947-4b1f-bac0-9a3b9c7233aa', 'Never use the paracetamol nomogram for staggered overdoses. Start Acetylcysteine immediately.', 'Snap 12-hour or simplified 2-bag IV acetylcysteine regimens reduce adverse hypersensitivity reactions. Reference: TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose.', 'TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose', 1789735204, 1789735204);
